+  let failure = "";
+  const scopes: string[] = [];
+  const indicators: import("./ReviewBoard").ReviewTabIndicator[] = [];
+  const load: typeof fetchReviewBoard = async (_cwd, scope) => {
+    scopes.push(scope);
